import React, { useState, useEffect } from 'react';
import { api } from '../services/api';
import CategoryManagement from './CategoryManagement';
import CategoryTable from './CategoryTable';
import ConfirmationModal from './ConfirmationModal';

function OperationalModel() {
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [editingCategory, setEditingCategory] = useState(null);
  const [showManagement, setShowManagement] = useState(false);
  const [showDeleteConfirmation, setShowDeleteConfirmation] = useState(false);
  const [categoryToDelete, setCategoryToDelete] = useState(null);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [draggedCategory, setDraggedCategory] = useState(null);
  const [dragOverZone, setDragOverZone] = useState(null);
  const [isDragging, setIsDragging] = useState(false);

  // Три области операционной модели (вертикально)
  const [zones, setZones] = useState({
    selfDiscovery: {
      id: 'selfDiscovery',
      name: 'Самопознание',
      icon: '🔍',
      description: 'Категории, связанные с изучением себя, внутренним развитием, духовными практиками',
      color: '#9b59b6',
      categories: []
    },
    selfRealization: {
      id: 'selfRealization',
      name: 'Самореализация',
      icon: '🚀',
      description: 'Категории, связанные с достижением целей, профессиональным ростом, реализацией потенциала',
      color: '#3498db',
      categories: []
    },
    service: {
      id: 'service',
      name: 'Служение',
      icon: '🤝',
      description: 'Категории, связанные с помощью другим, передачей знаний, менторством',
      color: '#e74c3c',
      categories: []
    }
  });

  useEffect(() => {
    loadCategories();
  }, []);

  useEffect(() => {
    if (categories.length > 0) {
      loadZonesFromStorage();
    }
  }, [categories]);

  const loadCategories = async () => {
    setLoading(true);
    try {
      const data = await api.getCategories();
      setCategories(data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const loadZonesFromStorage = () => {
    const savedZones = localStorage.getItem('operational_model_zones');
    if (savedZones) {
      const parsedZones = JSON.parse(savedZones);
      setZones(parsedZones);
    } else {
      // Инициализация зон с примерным распределением
      const initialZones = {
        selfDiscovery: {
          ...zones.selfDiscovery,
          categories: categories.filter(c => 
            ['Yoga', 'Math', 'Chinise', 'Oratory'].includes(c.name)
          )
        },
        selfRealization: {
          ...zones.selfRealization,
          categories: categories.filter(c => 
            ['SoftDev', 'MBA', 'Finance', 'Chess', 'Business', 'English'].includes(c.name)
          )
        },
        service: {
          ...zones.service,
          categories: categories.filter(c => 
            ['Boxing', 'Core'].includes(c.name)
          )
        }
      };
      setZones(initialZones);
    }
  };

  useEffect(() => {
    if (categories.length > 0 && zones) {
      localStorage.setItem('operational_model_zones', JSON.stringify(zones));
    }
  }, [zones]);

  const handleDeleteClick = (category) => {
    setCategoryToDelete(category);
    setShowDeleteConfirmation(true);
  };

  const handleConfirmDelete = async () => {
    if (!categoryToDelete) return;

    try {
      await api.deleteCategory(categoryToDelete.id);
      await loadCategories();
      setShowDeleteConfirmation(false);
      setCategoryToDelete(null);

      const updatedZones = { ...zones };
      Object.keys(updatedZones).forEach(zoneKey => {
        updatedZones[zoneKey].categories = updatedZones[zoneKey].categories.filter(
          c => c.id !== categoryToDelete.id
        );
      });
      setZones(updatedZones);
    } catch (err) {
      setError(err.message);
    }
  };

  const handleCancelDelete = () => {
    setShowDeleteConfirmation(false);
    setCategoryToDelete(null);
  };

  const handleDragStart = (e, category, sourceZoneId) => {
    setDraggedCategory({ category, sourceZoneId });
    setIsDragging(true);
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', JSON.stringify({ category, sourceZoneId }));

    const dragImage = document.createElement('div');
    dragImage.textContent = category.name;
    dragImage.style.position = 'absolute';
    dragImage.style.top = '-1000px';
    document.body.appendChild(dragImage);
    e.dataTransfer.setDragImage(dragImage, 0, 0);
    setTimeout(() => document.body.removeChild(dragImage), 0);
  };

  const handleDragEnd = () => {
    setDraggedCategory(null);
    setIsDragging(false);
    setDragOverZone(null);
  };

  const handleDragOver = (e, zoneId) => {
    e.preventDefault();
    if (!isDragging) return;
    setDragOverZone(zoneId);
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDragLeave = () => {
    setDragOverZone(null);
  };

  const handleDrop = (e, targetZoneId) => {
    e.preventDefault();
    setDragOverZone(null);

    if (!draggedCategory) return;

    const { category, sourceZoneId } = draggedCategory;

    if (sourceZoneId === targetZoneId) return;

    const updatedZones = { ...zones };
    updatedZones[sourceZoneId].categories = updatedZones[sourceZoneId].categories.filter(
      c => c.id !== category.id
    );
    updatedZones[targetZoneId].categories.push(category);

    setZones(updatedZones);
    setIsDragging(false);
    setDraggedCategory(null);
  };

  const handleCategoryClick = (category) => {
    setSelectedCategory(category);
  };

  const getCategoryColor = (color) => {
    return color || '#667eea';
  };

  const handleEditCategory = (category) => {
    setEditingCategory(category);
    setShowManagement(true);
  };

  if (loading) return <div className="loading">Загрузка операционной модели...</div>;
  if (error) return <div className="error">Ошибка: {error}</div>;

  // Если выбрана категория — показываем её страницу
  if (selectedCategory) {
    return (
      <div className="category-view-wrapper">
        <div className="category-view-header">
          <button 
            className="back-btn"
            onClick={() => setSelectedCategory(null)}
          >
            ← Назад
          </button>
          <h2>{selectedCategory.name}</h2>
          <button 
            className="edit-btn"
            onClick={() => handleEditCategory(selectedCategory)}
          >
            ✏️ Редактировать
          </button>
        </div>
        <CategoryTable 
          category={selectedCategory} 
          onBack={() => setSelectedCategory(null)}
          onEditCategory={handleEditCategory}
        />
      </div>
    );
  }

  return (
    <div className="operational-model">
      <div className="model-header">
        <h2>🏛️ Операционная модель</h2>
        <button 
          className="add-category-btn"
          onClick={() => {
            setEditingCategory(null);
            setShowManagement(true);
          }}
        >
          + Добавить категорию
        </button>
      </div>

      <div className="model-zones-vertical">
        {Object.values(zones).map(zone => (
          <div
            key={zone.id}
            className={`model-zone-vertical ${dragOverZone === zone.id ? 'drag-over' : ''}`}
            onDragOver={(e) => handleDragOver(e, zone.id)}
            onDragLeave={handleDragLeave}
            onDrop={(e) => handleDrop(e, zone.id)}
          >
            <div className="zone-header-vertical" style={{ backgroundColor: zone.color }}>
              <span className="zone-icon">{zone.icon}</span>
              <h3>{zone.name}</h3>
              <span className="zone-count-badge">{zone.categories.length}</span>
            </div>

            <div className="zone-description-vertical">
              {zone.description}
            </div>

            <div className="zone-categories-vertical">
              {zone.categories.length === 0 ? (
                <div className="empty-zone-vertical">
                  <p>Перетащите категорию сюда</p>
                </div>
              ) : (
                <div className="categories-grid-vertical">
                  {zone.categories.map(category => (
                    // Внутри zone.categories.map
<div
  key={category.id}
  className="category-card-vertical"
  draggable={true}
  onDragStart={(e) => handleDragStart(e, category, zone.id)}
  onDragEnd={handleDragEnd}
  onClick={() => handleCategoryClick(category)}
  style={{ 
    background: '#fef9e6',  // Бледно-желтый
    border: '1px solid #f0e4c0'
  }}
>
                      <div 
                        className="category-card-content-vertical"
                        onClick={() => handleCategoryClick(category)}
                      >
                        <span className="category-icon">{category.icon || '📦'}</span>
                        <span className="category-name">{category.name}</span>
                        {category.description && (
                          <span className="category-description">{category.description}</span>
                        )}
                      </div>
                      <div className="category-card-actions-vertical">
                        <button 
                          className="edit-btn"
                          onClick={(e) => {
                            e.stopPropagation();
                            handleEditCategory(category);
                          }}
                          title="Редактировать категорию"
                        >
                          ✏️
                        </button>
                        <button 
                          className="delete-btn"
                          onClick={(e) => {
                            e.stopPropagation();
                            handleDeleteClick(category);
                          }}
                          title="Удалить категорию"
                        >
                          🗑️
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {showManagement && (
        <CategoryManagement
          category={editingCategory}
          onClose={() => {
            setShowManagement(false);
            setEditingCategory(null);
          }}
          onUpdate={() => {
            loadCategories();
          }}
        />
      )}

      <ConfirmationModal
        isOpen={showDeleteConfirmation}
        title="Удаление категории"
        message={`Вы уверены, что хотите удалить категорию "${categoryToDelete?.name}"?`}
        warning="Это действие также удалит:"
        consequences={[
          "Все практики в этой категории",
          "Таблицу с данными категории",
          "Все связанные записи в календаре"
        ]}
        onConfirm={handleConfirmDelete}
        onCancel={handleCancelDelete}
      />
    </div>
  );
}

export default OperationalModel;
